"""Metrics collection for monitoring ingestion pipelines."""

import time
import functools
from typing import Any, Callable, Dict, List, TypeVar, cast

F = TypeVar('F', bound=Callable[..., Any])
_registry: Dict[str, Any] = {}


class Counter:
    _value: int

    def __init__(self, name: str, description: str = ""):
        self.name = name
        self.description = description
        self._value = 0

    def inc(self, amount: int = 1) -> None:
        self._value += amount

    def value(self) -> int:
        return self._value

    def reset(self) -> None:
        self._value = 0

    def to_dict(self) -> Dict[str, Any]:
        return {"name": self.name, "type": "counter", "value": self._value}


class Gauge:
    _value: float

    def __init__(self, name: str, description: str = ""):
        self.name = name
        self.description = description
        self._value = 0

    def set(self, value: float) -> None:
        self._value = value

    def inc(self, amount: float = 1) -> None:
        self._value += amount

    def dec(self, amount: float = 1) -> None:
        self._value -= amount

    def value(self) -> float:
        return self._value

    def to_dict(self) -> Dict[str, Any]:
        return {"name": self.name, "type": "gauge", "value": self._value}


class Histogram:
    _values: List[float]

    def __init__(self, name: str, description: str = ""):
        self.name = name
        self.description = description
        self._values = []

    def observe(self, value: float) -> None:
        self._values.append(value)

    def sum(self) -> float:
        return sum(self._values)

    def count(self) -> int:
        return len(self._values)

    def avg(self) -> float:
        return sum(self._values) / len(self._values) if self._values else 0

    def percentile(self, p: float) -> float:
        if not self._values:
            return 0
        sorted_vals = sorted(self._values)
        index = int(len(sorted_vals) * p / 100)
        return sorted_vals[max(0, min(index, len(sorted_vals) - 1))]

    def to_dict(self) -> Dict[str, Any]:
        if not self._values:
            return {"name": self.name, "type": "histogram", "count": 0}
        return {
            "name": self.name,
            "type": "histogram",
            "count": self.count(),
            "sum": self.sum(),
            "avg": self.avg(),
            "p50": self.percentile(50),
            "p90": self.percentile(90),
            "p99": self.percentile(99),
        }


def counter(name: str, description: str = "") -> Counter:
    if name not in _registry:
        _registry[name] = Counter(name, description)
    else:
        if not isinstance(_registry[name], Counter):
            raise ValueError(f"Metric {name} already registered as a different type")
    return cast(Counter, _registry[name])


def gauge(name: str, description: str = "") -> Gauge:
    if name not in _registry:
        _registry[name] = Gauge(name, description)
    else:
        if not isinstance(_registry[name], Gauge):
            raise ValueError(f"Metric {name} already registered as a different type")
    return cast(Gauge, _registry[name])


def histogram(name: str, description: str = "") -> Histogram:
    if name not in _registry:
        _registry[name] = Histogram(name, description)
    else:
        if not isinstance(_registry[name], Histogram):
            raise ValueError(f"Metric {name} already registered as a different type")
    return cast(Histogram, _registry[name])


def count_exceptions(metric_name: str) -> Callable[[F], F]:
    def decorator(f: F) -> F:
        @functools.wraps(f)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            try:
                return f(*args, **kwargs)
            except Exception:
                counter(metric_name).inc()
                raise

        return cast(F, wrapper)

    return decorator


def timer(metric_name: str) -> Callable[[F], F]:
    def decorator(f: F) -> F:
        @functools.wraps(f)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            start = time.time()
            result = f(*args, **kwargs)
            histogram(metric_name).observe(time.time() - start)
            return result

        return cast(F, wrapper)

    return decorator


def in_progress(metric_name: str) -> Callable[[F], F]:
    def decorator(f: F) -> F:
        @functools.wraps(f)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            gauge(metric_name).inc()
            try:
                return f(*args, **kwargs)
            finally:
                gauge(metric_name).dec()

        return cast(F, wrapper)

    return decorator


def all_metrics() -> List[Dict[str, Any]]:
    return [m.to_dict() for m in _registry.values()]


def reset_all() -> None:
    for m in _registry.values():
        m.reset()
