"""Simple in-memory cache with TTL support."""

import time
import functools
from typing import Any, Callable, Dict, Optional, TypeVar

F = TypeVar('F', bound=Callable[..., Any])


class TTLCache:
    _cache: Dict[str, Any]
    _timestamps: Dict[str, float]
    _ttls: Dict[str, int]

    def __init__(self, default_ttl: int = 300):
        self.default_ttl = default_ttl
        self._cache = {}
        self._timestamps = {}
        self._ttls = {}

    def set(self, key: str, value: Any, ttl: Optional[int] = None) -> None:
        self._cache[key] = value
        self._timestamps[key] = time.time()
        self._ttls[key] = ttl if ttl is not None else self.default_ttl

    def get(self, key: str, default: Any = None) -> Any:
        self._evict_expired()
        if key not in self._cache:
            return default
        return self._cache[key]

    def _evict_expired(self) -> None:
        now = time.time()
        expired_keys = [
            key for key in self._cache.keys()
            if now - self._timestamps[key] > self._ttls[key]
        ]
        for key in expired_keys:
            del self._cache[key]
            del self._timestamps[key]
            del self._ttls[key]

    def clear(self) -> None:
        self._cache.clear()
        self._timestamps.clear()
        self._ttls.clear()

    def size(self) -> int:
        self._evict_expired()
        return len(self._cache)

    def register(self, ttl: Optional[int] = None) -> Callable[[F], F]:
        def decorator(f: F) -> F:
            cache_key = f"__ttl_cache_{f.__module__}.{f.__name__}"

            @functools.wraps(f)
            def wrapper(*args: Any, **kwargs: Any) -> Any:
                # Simple cache key generation - in production use something more robust
                key = f"{cache_key}_{str(args)}_{str(sorted(kwargs.items()))}"
                cached = self.get(key)
                if cached is not None:
                    return cached
                result = f(*args, **kwargs)
                self.set(key, result, ttl)
                return result

            wrapper.cache = self  # type: ignore[attr-defined]
            wrapper.cache_clear = self.clear  # type: ignore[attr-defined]
            return cast(F, wrapper)

        return decorator


_default_cache: Optional[TTLCache] = None


def get_default_cache() -> TTLCache:
    global _default_cache
    if _default_cache is None:
        _default_cache = TTLCache()
    return _default_cache


def cache_with_ttl(ttl: Optional[int] = None) -> Callable[[F], F]:
    return get_default_cache().register(ttl)
