"""Data warehouse writer with buffered output."""

import csv
import json
import io
import logging
import os
import time
from typing import Any, cast, Collection, Dict, List, Optional, Union

from .models import Record, BatchResult

logger = logging.getLogger(__name__)


class BaseWriter:
    _buffer: List[Record]

    def __init__(self, output_path: str, buffer_size: int = 100):
        self.output_path = output_path
        self.buffer_size = buffer_size
        self._buffer = []
        self._total_written = 0

    def write_record(self, record: Record) -> None:
        self._buffer.append(record)
        if len(self._buffer) >= self.buffer_size:
            self.flush()

    def write_batch(self, records: List[Record]) -> None:
        for record in records:
            self.write_record(record)

    def flush(self) -> None:
        raise NotImplementedError

    def close(self) -> None:
        if self._buffer:
            self.flush()

    @property
    def total_written(self) -> int:
        return self._total_written

    def __enter__(self) -> "BaseWriter":
        return self

    def __exit__(self, exc_type: Any, exc_val: Any, exc_tb: Any) -> None:
        self.close()


class JsonWriter(BaseWriter):
    _first_write: bool

    def __init__(self, output_path: str, buffer_size: int = 100, pretty: bool = False):
        super().__init__(output_path, buffer_size)
        self.pretty = pretty
        self._first_write = True
        # Initialize the file with an opening bracket
        with open(self.output_path, "w") as f:
            f.write("[\n")

    def flush(self) -> None:
        if not self._buffer:
            return

        with open(self.output_path, "a") as f:
            for record in self._buffer:
                data = record.to_dict() if isinstance(record, Record) else record
                if not self._first_write:
                    f.write(",\n")
                if self.pretty:
                    f.write(json.dumps(data, indent=2, default=str))
                else:
                    f.write(json.dumps(data, default=str))
                self._first_write = False

        self._total_written += len(self._buffer)
        self._buffer.clear()
        logger.debug(f"Flushed {len(self._buffer)} records to {self.output_path}")

    def close(self) -> None:
        super().close()
        # Close the JSON array
        with open(self.output_path, "a") as f:
            f.write("\n]")


class CsvWriter(BaseWriter):
    fieldnames: Optional[List[str]]
    _header_written: bool

    def __init__(
        self, output_path: str, buffer_size: int = 100, fieldnames: Optional[List[str]] = None
    ):
        super().__init__(output_path, buffer_size)
        self.fieldnames = fieldnames
        self._header_written = False

    def flush(self) -> None:
        if not self._buffer:
            return

        rows: List[Dict[str, Any]] = []
        for record in self._buffer:
            data = record.to_dict() if isinstance(record, Record) else record
            rows.append(data)

        if not self._header_written and self.fieldnames is None:
            self.fieldnames = list(rows[0].keys())

        mode = "a" if self._header_written else "w"
        with open(self.output_path, mode, newline="") as f:
            writer = csv.DictWriter(
                f,
                fieldnames=cast(Collection[str], self.fieldnames),
                extrasaction="ignore"
            )
            if not self._header_written:
                writer.writeheader()
                self._header_written = True
            writer.writerows(rows)

        self._total_written += len(self._buffer)
        self._buffer.clear()


class NullWriter(BaseWriter):
    """Discards all records. Useful for dry-run or testing."""

    def flush(self) -> None:
        self._total_written += len(self._buffer)
        self._buffer.clear()


def create_writer(
    format: str, output_path: str, **kwargs: Any
) -> Union[JsonWriter, CsvWriter, NullWriter]:
    """Factory function to create the appropriate writer."""
    writers: Dict[str, Any] = {
        "json": JsonWriter,
        "csv": CsvWriter,
        "null": NullWriter,
    }
    writer_cls = writers.get(format)
    if writer_cls is None:
        raise ValueError(
            f"Unknown writer format: {format}. Available: {list(writers.keys())}"
        )
    return writer_cls(output_path, **kwargs)


def write_records(
    records: List[Record], output_path: str, format: str = "json", **kwargs: Any
) -> BatchResult:
    """Convenience function to write a list of records to a file."""
    result = BatchResult()
    start = time.time()

    with create_writer(format, output_path, **kwargs) as writer:
        for record in records:
            try:
                writer.write_record(record)
                result.add_success()
            except Exception as exc:
                result.add_failure(str(exc))

    result.duration_ms = (time.time() - start) * 1000
    return result
