"""JSON API polling source."""

import time
import logging
from typing import Any, Callable, Dict, List, Optional

import requests

from .models import Record, BatchResult

logger = logging.getLogger(__name__)


def fetch_page(
    base_url: str,
    endpoint: str,
    params: Optional[Dict[str, Any]] = None,
    headers: Optional[Dict[str, str]] = None,
    timeout: int = 30,
) -> Dict[str, Any]:
    """Fetch a single page from a JSON API."""
    url = f"{base_url.rstrip('/')}/{endpoint.lstrip('/')}"
    resp = requests.get(
        url, params=params or {}, headers=headers or {}, timeout=timeout
    )
    resp.raise_for_status()
    return resp.json()


def fetch_all_pages(
    base_url: str,
    endpoint: str,
    page_key: str = "page",
    data_key: str = "results",
    max_pages: int = 100,
) -> List[Record]:
    """Fetch all pages from a paginated API endpoint."""
    all_records: List[Record] = []
    page = 1
    while page <= max_pages:
        payload = fetch_page(base_url, endpoint, params={page_key: page})
        items = payload.get(data_key, [])
        if not items:
            break

        for item in items:
            item["_source"] = "api"
            item["_meta"] = {"endpoint": endpoint, "page": page}
            all_records.append(Record.from_dict(item))

        next_url = payload.get("next")
        if next_url is None:
            break
        page += 1

    return all_records


def poll_endpoint(
    base_url: str,
    endpoint: str,
    interval: int = 60,
    callback: Optional[Callable[[List[Record]], None]] = None,
    max_errors: int = 5,
) -> None:
    """Continuously poll an API endpoint and invoke callback with new records."""
    consecutive_errors = 0

    while consecutive_errors < max_errors:
        try:
            records = fetch_all_pages(base_url, endpoint)
            consecutive_errors = 0
            if callback is not None:
                callback(records)
            logger.info(f"Polled {len(records)} records from {endpoint}")
        except requests.RequestException as exc:
            consecutive_errors += 1
            logger.warning(f"Poll error ({consecutive_errors}/{max_errors}): {exc}")
        except Exception as exc:
            consecutive_errors += 1
            logger.error(f"Unexpected error polling {endpoint}: {exc}")

        time.sleep(interval)

    logger.error(
        f"Stopping poll for {endpoint} after {max_errors} consecutive errors"
    )


def build_auth_headers(
    api_key: Optional[str] = None, bearer_token: Optional[str] = None
) -> Dict[str, str]:
    """Build authentication headers for API requests."""
    headers: Dict[str, str] = {
        "Accept": "application/json",
        "Content-Type": "application/json",
    }
    if bearer_token:
        headers["Authorization"] = f"Bearer {bearer_token}"
    elif api_key:
        headers["X-API-Key"] = api_key
    return headers


def ingest_from_api(config: Dict[str, Any]) -> BatchResult:
    """Run a full API ingestion based on config dict."""
    base_url = config["base_url"]
    endpoints = config.get("endpoints", [])
    auth = build_auth_headers(
        api_key=config.get("api_key"), bearer_token=config.get("bearer_token")
    )

    result = BatchResult()
    for ep in endpoints:
        try:
            records = fetch_all_pages(
                base_url, ep, data_key=config.get("data_key", "results")
            )
            for rec in records:
                result.add_success()
        except Exception as exc:
            result.add_failure(f"Failed to ingest from {ep}: {exc}")
            logger.error(f"API ingestion error for {ep}: {exc}")

    return result
