"""Simple job scheduler for periodic ingestion tasks."""

import time
import logging
import traceback
from typing import Any, Callable, Dict, List, Optional

logger = logging.getLogger(__name__)


class Job:
    name: str
    fn: Callable[..., Any]
    interval: int
    args: tuple
    kwargs: Dict[str, Any]
    last_run: float
    run_count: int
    error_count: int
